package com.phoenix.business.web;
import com.phoenix.business.domain.User; import com.phoenix.business.repository.UserRepository; import com.phoenix.business.service.AuditService; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/users") @RequiredArgsConstructor @PreAuthorize("hasRole('OWNER')") public class UserController {private final UserRepository repo;private final PasswordEncoder encoder;private final AuditService audit; record Input(@NotBlank @Size(max=80) String username,@NotBlank @Size(max=120) String displayName,@NotNull User.Role role,@Pattern(regexp="^(?=.*[a-z])(?=.*[A-Z])(?=.*\\d).{10,72}$") String password,Boolean active){} record View(Long id,String username,String displayName,User.Role role,boolean active,boolean forcePasswordChange,java.time.Instant lastLoginAt,java.time.Instant createdAt){} private View v(User u){return new View(u.getId(),u.getUsername(),u.getDisplayName(),u.getRole(),u.isActive(),u.isForcePasswordChange(),u.getLastLoginAt(),u.getCreatedAt());}
@GetMapping public List<View> list(){return repo.findAll().stream().map(this::v).toList();}@PostMapping public View create(@Valid @RequestBody Input q){if(q.role()==User.Role.OWNER)throw new IllegalArgumentException("Additional owners cannot be created here");if(repo.findByUsernameIgnoreCase(q.username()).isPresent())throw new IllegalArgumentException("Username already exists");User u=new User();u.setUsername(q.username().trim());u.setDisplayName(q.displayName().trim());u.setRole(q.role());u.setActive(q.active()==null||q.active());u.setPasswordHash(encoder.encode(q.password()));u=repo.save(u);audit.record("STAFF_CREATED","USER",u.getId(),"Created "+u.getRole()+" account "+u.getUsername());return v(u);}@PutMapping("/{id}") public View update(@PathVariable Long id,@RequestBody Map<String,Object> q){User u=repo.findById(id).orElseThrow();if(u.getRole()==User.Role.OWNER)throw new IllegalArgumentException("Owner account cannot be changed here");if(q.containsKey("displayName"))u.setDisplayName(String.valueOf(q.get("displayName")));if(q.containsKey("role"))u.setRole(User.Role.valueOf(String.valueOf(q.get("role"))));if(q.containsKey("active"))u.setActive(Boolean.parseBoolean(String.valueOf(q.get("active"))));u=repo.save(u);audit.record("STAFF_UPDATED","USER",id,"Updated "+u.getUsername());return v(u);}@PostMapping("/{id}/reset-password") public void reset(@PathVariable Long id,@RequestBody Map<String,String> q){String password=q.get("password");if(password==null||!password.matches("^(?=.*[a-z])(?=.*[A-Z])(?=.*\\d).{10,72}$"))throw new IllegalArgumentException("Password does not meet strength requirements");User u=repo.findById(id).orElseThrow();u.setPasswordHash(encoder.encode(password));u.setForcePasswordChange(true);repo.save(u);audit.record("STAFF_PASSWORD_RESET","USER",id,"Password reset required for "+u.getUsername());}
}
